TOP=[(555,205),(525,145),(515,175),(515,300),(540,310),(512,300),(392,190)]
BOTTOM=[(560,1460),(515,1460),(510,1490),(515,1490),(535,1455),(505,1435),(515,1460)]
SLUG=['boundary','corridor','flooded','mechanism','sand','sun','return']
NAME=['경계 동굴','두아트 회랑','침수 신전','고대 장치','모래 성소','황금 태양전','귀환의 문']

def point(p, direction): return {'x':p[0]/PX-.5,'y':p[1]/PX-.8,'dir':direction}
def main():
    manifest=json.loads((ROOT/'세부맵1/두아트/manifest.json').read_text())
    art=json.loads((ROOT/'data/scene-art.json').read_text());checks=[]
    out=ROOT/'docs/consult/duat-field/maps';out.mkdir(parents=True,exist_ok=True)
    for i,f in enumerate(manifest['files'],1):
        src=ROOT/'세부맵1/두아트'/f['file'];raw=src.read_bytes()
        assert hashlib.sha256(raw).hexdigest()==f['sha256']
        file=f'duat-field-{i:02}-{SLUG[i-1]}.png';shutil.copyfile(src,ROOT/'docs/art/map-expansion'/file)
        floor=union_all([Polygon(p).buffer(0) for p in FLOORS[i]]).difference(union_all([Polygon(p).buffer(0) for p in OBSTACLES[i]]))
        image=Image.open(src).convert('RGB')
        if i == 2:
            boundary=json.loads((ROOT/'tools/maps/duat-boundaries/02.json').read_text())
            floor=Polygon(boundary['outer'], boundary['holes'])
            assert floor.is_valid, 'Approved corridor geometry invalid'
        mask=P.mask_from_geometry(floor,image)
        safe=P.safe_centres(mask,PX)
        top,bottom=TOP[i-1],BOTTOM[i-1]
        entTop=(top[0],top[1]+48); entBottom=(bottom[0],bottom[1]-48)
        path,upPixels=P.path(safe,entBottom,top);back,downPixels=P.path(safe,entTop,bottom)
        P.review(image,mask,path,out,i)
        ident=f'duat_{i:02}';entries={'bottom':point(entBottom,'up'),'top':point(entTop,'down')}
        exits=[]
        for label,p,to,at in [('top',top,f'duat_{i+1:02}' if i<7 else 'ombos','bottom' if i<7 else {'x':36,'y':10.6,'dir':'down'}),('bottom',bottom,f'duat_{i-1:02}' if i>1 else 'ombos','top' if i>1 else {'x':36,'y':10.6,'dir':'down'})]:
            exits.append({'id':label,'x0':(p[0]-20)/PX,'x1':(p[0]+20)/PX,'y0':(p[1]-10)/PX,'y1':(p[1]+10)/PX,'to':to,'at':at})
        data={'id':ident,'name':NAME[i-1],'tile':16,'scene':'duat','referenceScenes':[ident], 'legend':{'.':{'t':'sand'}},'rows':['.'*W]*H,'authoredCollision':{'width':W*PX,'height':H*PX,'shapes':[], 'pixelWalk': {'width':1024,'height':1536,'pixelsPerTile':PX,'rows':P.runs(mask)}},'entries':entries,'spawn':entries['bottom'],'exits':exits,'spots':[],'spawns':[],'roam':[], 'labels':[], 'note':'위로 계속 탐사하고, 아래로 돌아갈 수 있어.'}
        (ROOT/f'data/maps/{ident}.json').write_text(json.dumps(data,ensure_ascii=False,indent=1)+'\n')
        art[ident]={'file':R.ART+file,'fullMap':True,'lazy':True,'origin':[0,0],'scale':[16/PX]*2,'day':[0,0,1024,1536],'night':[0,0,1024,1536],'clip':[[0,0],[1024,0],[1024,1536],[0,1536]],'tintActors':False,'tintWorld':False}
        checks.append({'map':ident,'sha256':f['sha256'],'up':path,'down':back,'upPixelSteps':upPixels,'downPixelSteps':downPixels,'floor':[list(p.exterior.coords) for p in (floor.geoms if hasattr(floor,'geoms') else [floor])], 'holes':[list(h.coords) for p in (floor.geoms if hasattr(floor,'geoms') else [floor]) for h in p.interiors]})
        print(ident,'pixel paths',upPixels,downPixels,flush=True)
    (ROOT/'data/scene-art.json').write_text(R.dump(art)+'\n')
    (out/'paths.json').write_text(json.dumps({'pixelsPerTile':PX,'maps':checks},ensure_ascii=False)+'\n')
if __name__=='__main__':main()
